/**
 * @file Board.js
 * 
 * @description This component represents the game board for the "Člověče, nezlob se!" online game. 
 *              It handles game interactions, including rendering the board, managing game pieces, 
 *              responding to player actions, and updating the game state based on real-time events from the server.
 * 
 * @author Karolína Virágová (xvirag00)
 *
 * @props {Object} gameData - Initial game data including players and board pieces.
 * @props {Object} socket - The WebSocket connection for real-time communication with the server.
 * @props {function} handleReturnToMainScreen - Callback function to navigate back to the main screen.
 * 
 * @state {Array} players - List of players participating in the game.
 * @state {Array} pieces - List of all game pieces on the board.
 * @state {string|null} error - Error messages for failed actions.
 * @state {string} statusMessage - Message displaying the current game status.
 * @state {number|null} diceRoll - Result of the most recent dice roll.
 * @state {boolean} gameEnded - Indicates whether the game has ended.
 * @state {Array} score - Player scores at the end of the game.
 * @state {number} houseLength - Number of pieces successfully moved to the player's home area.
 * 
 * @functions
 * - `startNewGame`: Resets the game state and starts a new game.
 * - `handleTileClick`: Handles clicks on tiles, allowing players to move pieces.
 * - `renderPiece`: Renders game pieces on the board.
 * - `getTileColor`: Determines the color of each tile based on its purpose (path, home, or empty).
 * - `isCrossTile`: Checks whether a tile is part of the playable path.
 * 
 * @server_events
 * - `game:started`: Updates the game state when a new game starts.
 * - `game:updated`: Updates the position of pieces after a move.
 * - `game:diceRolled`: Updates the dice result and whether a new piece can be deployed.
 * - `game:ended`: Displays the final scores and marks the game as ended.
 * 
 */

import React, { useState, useMemo, useEffect } from 'react';
import './Board.css';
// eslint-disable-next-line no-unused-vars
import { getValueFromCoordinates, getCoordinatesFromValue } from './coordinates.js';
import Ended from './Ended';

const Board = ({ gameData, socket, handleReturnToMainScreen }) => {
  const gridSize = 11;
  const centerIndex = Math.floor(gridSize / 2);
  const [players, setPlayers] = useState(gameData.players || []);
  const [pieces, setPieces] = useState(gameData.board.pieces || []);
  const [error, setError] = useState(null);
  const [statusMessage, setStatusMessage] = useState("");
  const [diceRoll, setDiceRoll] = useState(null); // Stav pro výsledek hodu kostkou
  const [gameEnded, setGameEnded] = useState(false); // Stav pro kontrolu, jestli hra skončila
  const [score, setScore] = useState([]); // Stav pro skóre hráčů
  const [houseLength, setHouseLength] = useState(0); // Stav pro délku domečku

  useEffect(() => {
    if (!socket) return;

    socket.on('connect', () => {
      console.log('Socket connected: ', socket.id);
    });

    socket.on('disconnect', () => {
      console.log('Disconnected from server.');
    });

    socket.on('game:updated', (data) => {
      console.log('Received response from server:', data);
      const { updatedPiece, nextPlayerId } = data;
      if (updatedPiece) {
        const { ownerId, color, commonPosition } = updatedPiece;
            setStatusMessage("Position updated.");

        setPieces(prevPieces =>
          prevPieces.map(piece =>
            piece.ownerId === ownerId && piece.color === color
              ? { ...piece, commonPosition }
              : piece
          )
        );

        if (nextPlayerId) {
          setStatusMessage(`It's player ${nextPlayerId}'s turn.`);
        }
      }
      socket.emit('game:play');
    });

    socket.on('game:diceRolled', (data) => {
      const { playerId, dice, canDeploy } = data;
      setDiceRoll(dice);
      setStatusMessage(`Player ${playerId} rolled a ${dice}.`);

      if (canDeploy) {
        setStatusMessage(`Player ${playerId} can deploy a new piece!`);
        socket.emit('game:deployPiece');
      }
    });

    socket.on('game:started', (gameData) => {
      console.log('Game started:', gameData);

      if (gameData.board && Array.isArray(gameData.board.pieces)) {
        setPieces(gameData.board.pieces);
      } else {
        console.error('Invalid pieces data:', gameData.board?.pieces);
        setPieces([]); // Nastav prázdné pole, pokud data nejsou validní
      }
      setPlayers(gameData.players || []);
      socket.emit('game:play');
    });


        socket.on('game:ended', (data) => {
          console.log('Game has ended:', data);
          setGameEnded(true);
          setScore(data.score); 
          setHouseLength(data.houseLength);
        });

    return () => {      
      socket.off('game:started');

      socket.off('game:ended');
      socket.off('game:diceRolled');
      socket.off('game:updated');
      socket.off('game:ended');

    };
  }, [socket]);

  const startNewGame = () => {
    setPieces(gameData.board.pieces);
    setScore([]);
    setHouseLength(0);
    setGameEnded(false);
    const payload = {
      fillWithBots: false, 
    };
    socket.emit('game:start', payload, (response) => {
      console.log('Odpověď na start game:', response);

    });
    };

  const tileColorMap = useMemo(() => {
    const colorMap = new Map();
    setStatusMessage(`Hra started`);
    players.forEach((player, index) => {
      let tiles = [];
      if (index === 0) {
        tiles = [
          [4, 0], [5, 1], [5, 2], [5, 3], [5, 4], [0, 0], [0, 1], [1, 0], [1, 1]
        ];
      } else if (index === 1) {
        tiles = [
          [0, 6], [1, 5], [2, 5], [3, 5], [4, 5], [0, 9], [0, 10], [1, 9], [1, 10]
        ];
      } else if (index === 2) {
        tiles = [
          [6, 10], [5, 6], [5, 7], [5, 8], [5, 9], [9, 9], [10, 9], [9, 10], [10, 10]
        ];
      } else if (index === 3) {
        tiles = [
          [10, 4], [6, 5], [7, 5], [8, 5], [9, 5], [9, 0], [9, 1], [10, 0], [10, 1]
        ];
      }

      tiles.forEach(([row, col]) => {
        colorMap.set(`${row}-${col}`, player.color);
      });
    });
    return colorMap;
  }, [players]);

  const pieceMap = useMemo(() => {
    const map = new Map();
    pieces.forEach(piece => {
      const { row, col } = getCoordinatesFromValue(piece.commonPosition, piece.color);
      map.set(`${row}-${col}`, piece);
    });
    return map;
  }, [pieces]);

  const isCrossTile = (row, col) => {
    if (row === centerIndex && col === centerIndex) return false;
    return (
      (col >= centerIndex - 1 && col <= centerIndex + 1) ||
      (row >= centerIndex - 1 && row <= centerIndex + 1) ||
      (row <= 1 && col <= 1) ||
      (row >= 9 && col >= 9) ||
      (row <= 1 && col >= 9) ||
      (row >= 9 && col <= 1)
    );
  };

  const getTileColor = (row, col) => {
    if (!isCrossTile(row, col)) return 'white';
    return tileColorMap.get(`${row}-${col}`) || 'white';
  };

  const renderPiece = (row, col) => {
  // Získání figurky, která odpovídá dané pozici (row, col)
  const piece = pieces.find(p => {
    // Pokud má figurka přiřazenou pozici (commonPosition !== null)

      const coords = getCoordinatesFromValue(p.commonPosition, p);
      return coords.row === row && coords.col === col;

    // Pokud figurka ještě nemá pozici (commonPosition === null)
    // Kontrola, zda figurka není mimo povolený počet figur pro hráče

    // Zkontrolujeme, zda má figurka správnou výchozí pozici
  });

  // Pokud jsme našli figurku, vykreslíme ji
  if (piece) {
    return (
      <div
        className="piece"
        style={{
          backgroundColor: piece.color || 'gray',
          border: '2px solid white',
          width: '70%',
          height: '70%'
        }}
      />
    );
  }

  return null;
};



const handleTileClick = (row, col) => {
  const clickedPiece = pieceMap.get(`${row}-${col}`); // Zjistíme, zda na dané dlaždici je figurka

  if (clickedPiece) {
    // Pokud klikneme na figurku
    const payload = {
      commonPosition: clickedPiece.commonPosition, // Odesíláme pozici kliknuté figurky
    };

    console.log("Sending position:", payload);

    // Odeslání na server
    socket.emit('game:movePiece', payload, (data) => {
      if (!data) {
        setError(null);
        setStatusMessage("Position sent successfully.");
      } else {
        setError("Failed to send position.");
      }
    });
  } else {
    setError("No piece on this tile to select."); // Pokud není figurka na tomto políčku
  }
};


 // const rollDice = () => {
 //   if (socket) {
 //     console.log('Emitting game:play event');
 //     socket.emit('game:play');
 //   }
 // };

  return (
    <div className="board-container">
      {gameEnded ? (
        <Ended 
          score={score} 
          houseLength={houseLength}
          onReturnToApp={handleReturnToMainScreen} // Předáme funkci pro návrat
          onNewGame={startNewGame}  // Předání funkce pro novou hru
        />
      ) :  (
        <>
          {/* Zobrazení statusMessage nebo error */}
          {statusMessage && !error && <div className="status-message">{statusMessage}</div>}
          {error && statusMessage && <div className="error">{error}</div>}

          {/* Herní deska */}
          <div className="board">
            {Array.from({ length: gridSize }).map((_, row) => (
              <div key={row} className="board-row">
                {Array.from({ length: gridSize }).map((_, col) => (
                  <div
                    key={`${row}-${col}`}
                    className={`tile ${isCrossTile(row, col) ? '' : 'empty-tile'}`}
                    style={{
                      backgroundColor: getTileColor(row, col),
                    }}
                    onClick={() => handleTileClick(row, col)} // Přidání obsluhy kliknutí
                  >
                    {renderPiece(row, col)}
                  </div>
                ))}
              </div>
            ))}
          </div>

          {/* Tlačítko pro hod kostkou 
          <button onClick={rollDice} className="roll-dice-button">Roll Dice</button>
          {diceRoll !== null && <div className="dice-roll-result"></div>}*/}
        </>
      )}
    </div>
  );
};

export default Board;
